import numpy as np
def equation(eps, T, params):
    a,b,c,d,f,e,g,h,i,k = params[:10]
    num = a + b*T + (c + d*T)*eps + f*eps**2
    den = 1 + e*eps + g*T*eps + h*eps**2
    return -eps*num/den*np.exp(-(i + k/T)*eps)
